python -c "
import sys, json
sys.path.insert(0, 'scripts')
from miner2_20260730_factorlib import load_panel, factor_panel
import numpy as np, pandas as pd

P = load_panel()
R = P.pct_change()

def pos_frac(s, w): return (s > 0).rolling(w).mean()
def consistency(s, w):
    pf = (s > 0).rolling(w).mean()
    return (pf - 0.5).abs()

new = {
  'pos_frac_20': factor_panel(R, lambda s: pos_frac(s,20)),
  'consistency_20': factor_panel(R, lambda s: consistency(s,20)),
}

# load library artifacts
import base64, zlib, io
from pathlib import Path
arts = {}
for p in sorted(Path('factors').glob('*.json')):
    if p.name in ('factor_ensemble.json','bbz_20d.json'): continue
    try:
        d = json.load(open(p))
        art = d.get('validation',{}).get('signal_artifact')
        if not art: continue
        raw = zlib.decompress(base64.b64decode(art['data'])).decode()
        df = pd.read_csv(io.StringIO(raw), index_col=0, parse_dates=True)
        arts[d['factor_id']] = df
    except Exception as e:
        print('skip', p.name, e)

def spearman_panel(a, b):
    common = a.index.intersection(b.index)
    ac = a.loc[common].stack(); bc = b.loc[common].stack()
    m = ac.notna() & bc.notna()
    if m.sum() < 30: return 0.0
    return float(ac[m].rank().corr(bc[m].rank()))

for name, panel in new.items():
    print('===', name)
    for fid, df in sorted(arts.items()):
        rho = spearman_panel(panel, df)
        flag = ' *** HIGH' if abs(rho) > 0.5 else ''
        print(f'  {fid}: rho={rho:.4f}{flag}')
"

